import java.util.*;

public class Main {
    static class Node { int key, val; Node prev, next; Node(int k, int v) { key = k; val = v; } }
    static int cap = 2;
    static Map<Integer, Node> map = new HashMap<>();          // key -> node: O(1) lookup
    static Node head = new Node(0, 0), tail = new Node(0, 0); // dummy ends: no null checks

    static void unlink(Node n) { n.prev.next = n.next; n.next.prev = n.prev; }
    static void addFront(Node n) {                            // most recent sits right after head
        n.next = head.next; n.prev = head; head.next.prev = n; head.next = n;
    }
    static int get(int key) {
        Node n = map.get(key);
        if (n == null) return -1;
        unlink(n); addFront(n);                               // a read also refreshes recency
        return n.val;
    }
    static void put(int key, int val) {
        Node n = map.get(key);
        if (n != null) { n.val = val; unlink(n); addFront(n); return; }
        if (map.size() == cap) {                              // full: least recent is tail.prev
            Node old = tail.prev; unlink(old); map.remove(old.key);
            System.out.println("  evict key " + old.key);
        }
        n = new Node(key, val); map.put(key, n); addFront(n);
    }
    // Time: O(1) per get/put. Space: O(capacity).
    public static void main(String[] args) {
        head.next = tail; tail.prev = head;
        int[][] ops = {{1,1,10},{1,2,20},{0,1,0},{1,3,30},{0,2,0},{1,4,40},{0,1,0},{0,3,0},{0,4,0}};
        System.out.println("LRU cache, capacity " + cap);
        for (int[] op : ops) {
            if (op[0] == 1) { System.out.println("put(" + op[1] + "," + op[2] + ")"); put(op[1], op[2]); }
            else System.out.println("get(" + op[1] + ") = " + get(op[1]));
        }
    }
}

