#include <bits/stdc++.h>
using namespace std;

struct Node { int key, val; Node *prev, *next; };
int cap = 2;
unordered_map<int, Node*> table;                 // key -> node: O(1) lookup
Node *head = new Node{0, 0, nullptr, nullptr};   // dummy ends: no null checks
Node *tail = new Node{0, 0, nullptr, nullptr};

void unlink(Node* n) { n->prev->next = n->next; n->next->prev = n->prev; }
void addFront(Node* n) {                         // most recent sits right after head
    n->next = head->next; n->prev = head; head->next->prev = n; head->next = n;
}
int get(int key) {
    auto it = table.find(key);
    if (it == table.end()) return -1;
    unlink(it->second); addFront(it->second);    // a read also refreshes recency
    return it->second->val;
}
void put(int key, int val) {
    auto it = table.find(key);
    if (it != table.end()) { it->second->val = val; unlink(it->second); addFront(it->second); return; }
    if ((int)table.size() == cap) {              // full: least recent is tail->prev
        Node* old = tail->prev; unlink(old); table.erase(old->key);
        cout << "  evict key " << old->key << "\n";
        delete old;
    }
    Node* n = new Node{key, val, nullptr, nullptr};
    table[key] = n; addFront(n);
}
// Time: O(1) per get/put. Space: O(capacity).
int main() {
    head->next = tail; tail->prev = head;
    int ops[9][3] = {{1,1,10},{1,2,20},{0,1,0},{1,3,30},{0,2,0},{1,4,40},{0,1,0},{0,3,0},{0,4,0}};
    cout << "LRU cache, capacity " << cap << "\n";
    for (auto& op : ops) {
        if (op[0] == 1) { cout << "put(" << op[1] << "," << op[2] << ")\n"; put(op[1], op[2]); }
        else cout << "get(" << op[1] << ") = " << get(op[1]) << "\n";
    }
    return 0;
}

