class Node { public int key, val; public Node prev, next; public Node(int k, int v) { key = k; val = v; } }

class Program {
    static int cap = 2;
    static Dictionary<int, Node> map = new Dictionary<int, Node>();   // key -> node: O(1) lookup
    static Node head = new Node(0, 0), tail = new Node(0, 0);         // dummy ends: no null checks

    static void Unlink(Node n) { n.prev.next = n.next; n.next.prev = n.prev; }
    static void AddFront(Node n) {                                    // most recent sits right after head
        n.next = head.next; n.prev = head; head.next.prev = n; head.next = n;
    }
    static int Get(int key) {
        Node n;
        if (!map.TryGetValue(key, out n)) return -1;
        Unlink(n); AddFront(n);                                       // a read also refreshes recency
        return n.val;
    }
    static void Put(int key, int val) {
        Node n;
        if (map.TryGetValue(key, out n)) { n.val = val; Unlink(n); AddFront(n); return; }
        if (map.Count == cap) {                                       // full: least recent is tail.prev
            Node old = tail.prev; Unlink(old); map.Remove(old.key);
            Console.WriteLine("  evict key " + old.key);
        }
        n = new Node(key, val); map[key] = n; AddFront(n);
    }
    // Time: O(1) per get/put. Space: O(capacity).
    static void Main() {
        head.next = tail; tail.prev = head;
        int[][] ops = { new[]{1,1,10}, new[]{1,2,20}, new[]{0,1,0}, new[]{1,3,30}, new[]{0,2,0},
                        new[]{1,4,40}, new[]{0,1,0}, new[]{0,3,0}, new[]{0,4,0} };
        Console.WriteLine("LRU cache, capacity " + cap);
        foreach (int[] op in ops) {
            if (op[0] == 1) { Console.WriteLine("put(" + op[1] + "," + op[2] + ")"); Put(op[1], op[2]); }
            else Console.WriteLine("get(" + op[1] + ") = " + Get(op[1]));
        }
    }
}

