public class Main {
    // Counts cache hits. lfu=false: evict the least recently used entry.
    // lfu=true: evict the entry with the lowest use count (ties: the older one).
    static int simulate(int[] trace, int cap, boolean lfu) {
        int[] key = new int[cap], cnt = new int[cap], last = new int[cap];
        int size = 0, hits = 0;
        for (int t = 0; t < trace.length; t++) {
            int x = trace[t], at = -1;
            for (int i = 0; i < size; i++) if (key[i] == x) at = i;
            if (at >= 0) { hits++; cnt[at]++; last[at] = t; continue; }   // hit: refresh stats
            if (size < cap) at = size++;
            else {                                                       // full: pick a victim
                at = 0;
                for (int i = 1; i < cap; i++) {
                    boolean worse = lfu ? (cnt[i] < cnt[at] || (cnt[i] == cnt[at] && last[i] < last[at]))
                                        : last[i] < last[at];
                    if (worse) at = i;
                }
            }
            key[at] = x; cnt[at] = 1; last[at] = t;                      // new entry starts at count 1
        }
        return hits;
    }
    // Time: O(N * capacity) for this simple scan version. Space: O(capacity).
    public static void main(String[] args) {
        // hot keys 1,2,3, then a scan of one-off keys 10..13, then the hot keys again
        int[] trace = {1,2,3,1,2,3,1,2,3,10,11,12,13,1,2,3,1,2,3};
        StringBuilder sb = new StringBuilder("trace:");
        for (int x : trace) sb.append(" ").append(x);
        System.out.println(sb);
        System.out.println("capacity: 4");
        System.out.println("LRU hits: " + simulate(trace, 4, false) + " of " + trace.length);
        System.out.println("LFU hits: " + simulate(trace, 4, true) + " of " + trace.length);
    }
}

