import java.util.*;

public class Main {
    static final int MAXL = 4;
    static List<Integer> keys = new ArrayList<>();
    static List<int[]> nxt = new ArrayList<>();   // nxt.get(node)[level] = next node id, -1 = end
    static int seed = 42;

    // Small fixed random generator so every run (and every language) gives the same list.
    static boolean coin() { seed = (seed * 75 + 74) % 65537; return seed % 2 == 1; }
    static int newNode(int key) {
        int[] a = new int[MAXL]; Arrays.fill(a, -1);
        keys.add(key); nxt.add(a); return keys.size() - 1;
    }
    static void insert(int key) {
        int[] update = new int[MAXL]; int x = 0;
        for (int l = MAXL - 1; l >= 0; l--) {          // last node before key on each level
            while (nxt.get(x)[l] != -1 && keys.get(nxt.get(x)[l]) < key) x = nxt.get(x)[l];
            update[l] = x;
        }
        int lvl = 1;
        while (lvl < MAXL && coin()) lvl++;            // promote with probability 1/2
        int id = newNode(key);
        for (int l = 0; l < lvl; l++) { nxt.get(id)[l] = nxt.get(update[l])[l]; nxt.get(update[l])[l] = id; }
    }
    static int search(int key) {                       // returns the number of moves to the right
        int x = 0, steps = 0;
        for (int l = MAXL - 1; l >= 0; l--)            // go right while possible, then drop a level
            while (nxt.get(x)[l] != -1 && keys.get(nxt.get(x)[l]) <= key) { x = nxt.get(x)[l]; steps++; }
        return steps;
    }
    // Expected time: O(log N) search and insert. Space: O(N) expected.
    public static void main(String[] args) {
        newNode(0);                                    // node 0 is the head
        for (int i = 0; i < 16; i++) insert(((5 * i) % 16) * 3 + 1);
        for (int l = MAXL - 1; l >= 0; l--) {
            StringBuilder sb = new StringBuilder("L" + l + ":");
            for (int x = nxt.get(0)[l]; x != -1; x = nxt.get(x)[l]) sb.append(" ").append(keys.get(x));
            System.out.println(sb);
        }
        for (int t : new int[]{22, 46})
            System.out.println("search " + t + ": " + search(t) + " moves with lanes, "
                + ((t - 1) / 3 + 1) + " moves on the bottom list alone");
    }
}

