public class Main {
    static final int M = 64, K = 3;                 // 64 bits, 3 hash functions
    static boolean[] bits = new boolean[M];

    static long h(long x) { return (x * x * 31 + x * 7919 + 12345) % 1000003; }
    // Double hashing: position i = h1 + i * h2, so two hashes give K positions.
    static int pos(int x, int i) { return (int) ((h(x) + i * (1 + h(x + 1000) % 63)) % M); }
    static void add(int x) { for (int i = 0; i < K; i++) bits[pos(x, i)] = true; }
    static boolean mightContain(int x) {
        for (int i = 0; i < K; i++) if (!bits[pos(x, i)]) return false;  // one 0 bit = certainly absent
        return true;
    }
    // Time: O(K) per add/query. Space: M bits, independent of item size.
    public static void main(String[] args) {
        double n = 500000000.0, p = 0.001, ln2 = Math.log(2);
        double bitsPerItem = -Math.log(p) / (ln2 * ln2);
        long tenths = Math.round(bitsPerItem * 10);
        System.out.println("500 million items at 0.1%: " + (tenths / 10) + "." + (tenths % 10)
            + " bits per item, about " + Math.round(n * bitsPerItem / 8 / 1e6) + " MB, k = "
            + Math.round(bitsPerItem * ln2) + " hashes");

        System.out.println("small filter: 64 bits, 3 hashes, items 101..110 added");
        for (int x = 101; x <= 110; x++) add(x);
        for (int q : new int[]{105, 110, 500, 999})
            System.out.println("query " + q + ": " + (mightContain(q) ? "maybe present" : "definitely not present"));
        int fp = 0;
        for (int q = 1000; q < 2000; q++) if (mightContain(q)) fp++;   // none of these were added
        System.out.println("false positives among 1000 absent items: " + fp);
    }
}

