import java.util.*;

public class Main {
    static long h(long x) { return (x * x * 31 + x * 7919 + 12345) % 1000003; }

    // Each server gets `vnodes` points on the ring. One entry = position * 100 + server id.
    static long[] buildRing(int servers, int vnodes) {
        long[] ring = new long[servers * vnodes];
        for (int s = 0; s < servers; s++)
            for (int v = 0; v < vnodes; v++)
                ring[s * vnodes + v] = h(50000 + s * 1000 + v) * 100 + s;
        Arrays.sort(ring);
        return ring;
    }
    // Owner = first point clockwise from the key's position (binary search, wrap to 0).
    static int owner(long[] ring, int key) {
        long target = h(key) * 100;
        int lo = 0, hi = ring.length;
        while (lo < hi) { int mid = (lo + hi) / 2; if (ring[mid] < target) lo = mid + 1; else hi = mid; }
        if (lo == ring.length) lo = 0;
        return (int) (ring[lo] % 100);
    }
    // Lookup: O(log V) for V points. Space: O(V). Adding a server moves about 1/N of the keys.
    public static void main(String[] args) {
        int keys = 1000, movedMod = 0, movedRing = 0;
        long[] ring4 = buildRing(4, 50), ring5 = buildRing(5, 50);
        int[] load = new int[5];
        for (int k = 0; k < keys; k++) {
            if (h(k) % 4 != h(k) % 5) movedMod++;              // hash % N remaps almost everything
            if (owner(ring4, k) != owner(ring5, k)) movedRing++;
            load[owner(ring5, k)]++;
        }
        System.out.println("1000 keys, servers 4 -> 5, 50 virtual nodes per server");
        System.out.println("hash % N : " + movedMod + " keys moved");
        System.out.println("ring     : " + movedRing + " keys moved (ideal is about 200)");
        StringBuilder sb = new StringBuilder("ring load per server:");
        for (int x : load) sb.append(" ").append(x);
        System.out.println(sb);
    }
}

