public class Main {
    static long h(long x) { return (x * x * 31 + x * 7919 + 12345) % 1000003; }
    // Every (key, server) pair gets its own score; no ring and no shared state is needed.
    static long score(int key, int s) { return h(key * 37L + s * 10007L + 1); }

    // The owner is the live server with the highest score for this key: O(N) per lookup.
    static int owner(int key, boolean[] alive) {
        int best = -1;
        for (int s = 0; s < alive.length; s++)
            if (alive[s] && (best < 0 || score(key, s) > score(key, best))) best = s;
        return best;
    }
    // Time: O(N servers) per lookup. Space: O(1) beyond the server list.
    public static void main(String[] args) {
        boolean[] alive = {true, true, true, true, true};
        int[] before = new int[1000], load = new int[5];
        for (int k = 0; k < 1000; k++) { before[k] = owner(k, alive); load[before[k]]++; }
        StringBuilder sb = new StringBuilder("1000 keys on 5 servers, load:");
        for (int x : load) sb.append(" ").append(x);
        System.out.println(sb);

        alive[2] = false;                                  // server 2 dies
        int moved = 0;
        for (int k = 0; k < 1000; k++) if (owner(k, alive) != before[k]) moved++;
        System.out.println("server 2 removed: " + moved + " keys moved, " + load[2] + " keys lived on server 2");

        alive[2] = true;                                   // replicas = the two best scores
        int first = owner(7, alive);
        alive[first] = false;
        int second = owner(7, alive);
        System.out.println("key 7 replicas: server " + first + " then server " + second);
    }
}

