import java.util.*;

public class Main {
    static Map<String, List<Integer>> times = new HashMap<>();   // key -> sorted timestamps
    static Map<String, List<String>> vals = new HashMap<>();     // key -> values, same order

    static void set(String key, String value, int t) {           // timestamps arrive increasing: append
        times.computeIfAbsent(key, k -> new ArrayList<>()).add(t);
        vals.computeIfAbsent(key, k -> new ArrayList<>()).add(value);
        System.out.println("set(" + key + ", \"" + value + "\", " + t + ")");
    }
    static String get(String key, int t) {
        List<Integer> ts = times.get(key);
        if (ts == null) return "";
        int lo = 0, hi = ts.size();                              // find the first timestamp > t
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (ts.get(mid) <= t) lo = mid + 1; else hi = mid;
        }
        return lo == 0 ? "" : vals.get(key).get(lo - 1);         // the one just before it is the answer
    }
    // Time: set O(1), get O(log V) for V versions of the key. Space: O(total sets).
    public static void main(String[] args) {
        set("price", "100", 1);
        set("price", "120", 4);
        set("price", "90", 7);
        for (int t : new int[]{0, 1, 5, 7, 10})
            System.out.println("get(price, " + t + ") = \"" + get("price", t) + "\"");
        System.out.println("get(stock, 3) = \"" + get("stock", 3) + "\"");
    }
}

