    static void Set(string key, string value, int t) {           // timestamps arrive increasing: append
        if (!times.ContainsKey(key)) { times[key] = new List<int>(); vals[key] = new List<string>(); }
        times[key].Add(t);
        vals[key].Add(value);
        Console.WriteLine("set(" + key + ", \"" + value + "\", " + t + ")");
    }
    static string Get(string key, int t) {
        List<int> ts;
        if (!times.TryGetValue(key, out ts)) return "";
        int lo = 0, hi = ts.Count;                               // find the first timestamp > t
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (ts[mid] <= t) lo = mid + 1; else hi = mid;
        }
        return lo == 0 ? "" : vals[key][lo - 1];                 // the one just before it is the answer
    }
    // Time: set O(1), get O(log V) for V versions of the key. Space: O(total sets).
    static void Main() {
        Set("price", "100", 1);
        Set("price", "120", 4);
        Set("price", "90", 7);
        foreach (int t in new[] { 0, 1, 5, 7, 10 })
            Console.WriteLine("get(price, " + t + ") = \"" + Get("price", t) + "\"");
        Console.WriteLine("get(stock, 3) = \"" + Get("stock", 3) + "\"");
    }
}

