import java.util.*;

public class Main {
    static Deque<Iterator<?>> stack = new ArrayDeque<>();   // one iterator per list we are inside
    static Integer pending = null;                          // next integer, fetched but not returned yet

    static boolean hasNext() {                              // safe to call many times: it only fills pending
        while (pending == null && !stack.isEmpty()) {
            Iterator<?> it = stack.peek();
            if (!it.hasNext()) { stack.pop(); continue; }   // this list is finished
            Object x = it.next();
            if (x instanceof Integer) pending = (Integer) x;
            else stack.push(((List<?>) x).iterator());      // go one level deeper, lazily
        }
        return pending != null;
    }
    static int next() {
        if (!hasNext()) throw new NoSuchElementException();
        int v = pending; pending = null;
        return v;
    }
    // Total time: O(N + L) for N integers and L lists. Space: O(D) for nesting depth D.
    public static void main(String[] args) {
        List<Object> nested = List.of(1, List.of(2, List.of(3, 4)), List.of(), 5);
        System.out.println("nested list: [1,[2,[3,4]],[],5]");
        stack.push(nested.iterator());
        StringBuilder sb = new StringBuilder("flattened:");
        while (hasNext() && hasNext()) sb.append(" ").append(next());   // calling hasNext twice is harmless
        System.out.println(sb);
        System.out.println("hasNext after the end: " + (hasNext() ? "yes" : "no"));
    }
}

