#include <bits/stdc++.h>
using namespace std;

struct Node { bool isInt; int val; vector<Node> kids; };   // an integer or a list
Node I(int v) { return Node{true, v, {}}; }
Node L(vector<Node> kids) { return Node{false, 0, kids}; }

vector<pair<const Node*, size_t>> st;   // one (list, index) frame per list we are inside
bool has = false;                       // is there an integer fetched but not returned yet?
int pending = 0;

bool hasNext() {                        // safe to call many times: it only fills pending
    while (!has && !st.empty()) {
        const Node* list = st.back().first;
        if (st.back().second == list->kids.size()) { st.pop_back(); continue; }   // list finished
        const Node* x = &list->kids[st.back().second++];
        if (x->isInt) { pending = x->val; has = true; }
        else st.push_back({x, 0});      // go one level deeper, lazily
    }
    return has;
}
int nextValue() {
    if (!hasNext()) throw runtime_error("no more elements");
    has = false;
    return pending;
}
// Total time: O(N + L) for N integers and L lists. Space: O(D) for nesting depth D.
int main() {
    Node nested = L({I(1), L({I(2), L({I(3), I(4)})}), L({}), I(5)});
    cout << "nested list: [1,[2,[3,4]],[],5]\n";
    st.push_back({&nested, 0});
    cout << "flattened:";
    while (hasNext() && hasNext()) cout << " " << nextValue();   // calling hasNext twice is harmless
    cout << "\n";
    cout << "hasNext after the end: " << (hasNext() ? "yes" : "no") << "\n";
    return 0;
}

