using System;
using System.Collections.Generic;

class Program {
    static List<object[]> lists = new List<object[]>();   // stack: the lists we are inside
    static List<int> idx = new List<int>();               // stack: position inside each of them
    static bool has = false;                              // an integer fetched but not returned yet?
    static int pending = 0;

    static bool HasNext() {                               // safe to call many times: it only fills pending
        while (!has && lists.Count > 0) {
            int top = lists.Count - 1;
            if (idx[top] == lists[top].Length) { lists.RemoveAt(top); idx.RemoveAt(top); continue; }
            object x = lists[top][idx[top]];
            idx[top] = idx[top] + 1;
            if (x is int) { pending = (int)x; has = true; }
            else { lists.Add((object[])x); idx.Add(0); }  // go one level deeper, lazily
        }
        return has;
    }
    static int Next() {
        if (!HasNext()) throw new InvalidOperationException("no more elements");
        has = false;
        return pending;
    }
    // Total time: O(N + L) for N integers and L lists. Space: O(D) for nesting depth D.
    static void Main() {
        object[] nested = { 1, new object[] { 2, new object[] { 3, 4 } }, new object[] { }, 5 };
        Console.WriteLine("nested list: [1,[2,[3,4]],[],5]");
        lists.Add(nested); idx.Add(0);
        string line = "flattened:";
        while (HasNext() && HasNext()) line += " " + Next();   // calling HasNext twice is harmless
        Console.WriteLine(line);
        Console.WriteLine("hasNext after the end: " + (HasNext() ? "yes" : "no"));
    }
}

