import java.util.*;

public class Main {
    static final int W = 300;                     // window length in seconds
    static int[] times = new int[W];              // which second each bucket currently holds
    static int[] counts = new int[W];             // hits recorded for that second

    static void hit(int t) {
        int i = t % W;
        if (times[i] != t) { times[i] = t; counts[i] = 0; }   // bucket holds an old second: recycle it
        counts[i]++;
    }
    static int getHits(int t) {
        int total = 0;
        for (int i = 0; i < W; i++)
            if (t - times[i] < W) total += counts[i];         // only buckets inside the window count
        return total;
    }
    // Time: hit O(1), getHits O(300). Space: O(300) no matter how much traffic arrives.
    public static void main(String[] args) {
        Arrays.fill(times, -1000);                // "very old", so empty buckets are ignored
        for (int t : new int[]{1, 1, 2, 300}) { hit(t); System.out.println("hit at t=" + t); }
        System.out.println("getHits(300) = " + getHits(300));
        hit(301);
        System.out.println("hit at t=301 (reuses the bucket that held second 1)");
        System.out.println("getHits(301) = " + getHits(301));
        System.out.println("getHits(600) = " + getHits(600));
    }
}

