import java.util.*;

public class Main {
    static class Node { Map<Character, Node> kids = new HashMap<>(); List<Integer> top = new ArrayList<>(); }
    static String[] words = {"car", "card", "care", "cart", "cat", "dog"};
    static int[] score = {50, 30, 40, 20, 60, 10};
    static final int K = 3;
    static Node root = new Node();

    static void insert(int id) {
        Node cur = root;
        for (char c : words[id].toCharArray()) {
            cur = cur.kids.computeIfAbsent(c, x -> new Node());
            cur.top.add(id);                                  // every node on the path may list this word
            cur.top.sort((a, b) -> score[b] - score[a]);      // best score first
            if (cur.top.size() > K) cur.top.remove(K);        // keep only the K best
        }
    }
    static String suggest(String prefix) {                    // walk the prefix, return the cached list
        Node cur = root;
        for (char c : prefix.toCharArray()) { cur = cur.kids.get(c); if (cur == null) return " (none)"; }
        StringBuilder sb = new StringBuilder();
        for (int id : cur.top) sb.append(" ").append(words[id]).append("(").append(score[id]).append(")");
        return sb.toString();
    }
    // Query: O(prefix length + K). Insert: O(word length * K log K). Space: O(nodes * K).
    public static void main(String[] args) {
        StringBuilder sb = new StringBuilder("words:");
        for (int i = 0; i < words.length; i++) { insert(i); sb.append(" ").append(words[i]).append("(").append(score[i]).append(")"); }
        System.out.println(sb);
        for (String p : new String[]{"ca", "car", "d", "x"})
            System.out.println("\"" + p + "\" ->" + suggest(p));
    }
}

