import java.util.*;

public class Main {
    static final int SHARDS = 4, CAP = 2;                  // 4 small LRU caches, 2 entries each
    static List<List<Integer>> shard = new ArrayList<>();  // per shard: keys, least recent first
    static int evictions = 0;

    // In real code each shard has its own lock, so threads on different shards never wait.
    static void access(int key) {
        int s = key % SHARDS;                              // only shard s (and its lock) is touched
        List<Integer> lru = shard.get(s);
        String msg = "access " + key + " -> shard " + s;
        lru.remove(Integer.valueOf(key));                  // move the key to the most-recent end
        lru.add(key);
        if (lru.size() > CAP) { msg += ", evicts " + lru.remove(0); evictions++; }
        System.out.println(msg);
    }
    // Time: O(shard capacity) here (list scan); O(1) with map + linked list. Space: O(total capacity).
    public static void main(String[] args) {
        for (int i = 0; i < SHARDS; i++) shard.add(new ArrayList<>());
        for (int key : new int[]{1, 5, 2, 1, 9, 3, 13}) access(key);
        int stored = 0;
        for (int i = 0; i < SHARDS; i++) {
            StringBuilder sb = new StringBuilder("shard " + i + ":");
            for (int k : shard.get(i)) sb.append(" ").append(k);
            System.out.println(sb);
            stored += shard.get(i).size();
        }
        // The trade-off: eviction is decided per shard, not for the cache as a whole.
        System.out.println("stored " + stored + " of " + (SHARDS * CAP) + " slots, but " + evictions + " evictions already happened");
    }
}

