    static List<List<int>> shard = new List<List<int>>();       // per shard: keys, least recent first
    static int evictions = 0;

    // In real code each shard has its own lock, so threads on different shards never wait.
    static void Access(int key) {
        int s = key % SHARDS;                                   // only shard s (and its lock) is touched
        List<int> lru = shard[s];
        string msg = "access " + key + " -> shard " + s;
        lru.Remove(key);                                        // move the key to the most-recent end
        lru.Add(key);
        if (lru.Count > CAP) { msg += ", evicts " + lru[0]; lru.RemoveAt(0); evictions++; }
        Console.WriteLine(msg);
    }
    // Time: O(shard capacity) here (list scan); O(1) with map + linked list. Space: O(total capacity).
    static void Main() {
        for (int i = 0; i < SHARDS; i++) shard.Add(new List<int>());
        foreach (int key in new[] { 1, 5, 2, 1, 9, 3, 13 }) Access(key);
        int stored = 0;
        for (int i = 0; i < SHARDS; i++) {
            string line = "shard " + i + ":";
            foreach (int k in shard[i]) line += " " + k;
            Console.WriteLine(line);
            stored += shard[i].Count;
        }
        // The trade-off: eviction is decided per shard, not for the cache as a whole.
        Console.WriteLine("stored " + stored + " of " + (SHARDS * CAP) + " slots, but " + evictions + " evictions already happened");
    }
}

