public class Main {
    static String[] key = {"A", "B", "C", "D"};
    static int[] cnt = {1, 2, 3, 4};               // a valid min-heap ordered by use count
    static int n = 4;

    static void show() {
        StringBuilder sb = new StringBuilder("heap:");
        for (int i = 0; i < n; i++) sb.append(" ").append(key[i]).append(":").append(cnt[i]);
        System.out.println(sb);
    }
    static int trueMin() {                         // slow but obviously correct: scan everything
        int m = 0;
        for (int i = 1; i < n; i++) if (cnt[i] < cnt[m]) m = i;
        return m;
    }
    static void siftDown(int i) {                  // the repair step the buggy code never runs
        while (true) {
            int l = 2 * i + 1, r = 2 * i + 2, m = i;
            if (l < n && cnt[l] < cnt[m]) m = l;
            if (r < n && cnt[r] < cnt[m]) m = r;
            if (m == i) return;
            String tk = key[i]; key[i] = key[m]; key[m] = tk;
            int tc = cnt[i]; cnt[i] = cnt[m]; cnt[m] = tc;
            i = m;
        }
    }
    // siftDown is O(log N); finding a key inside a heap first is O(N). Neither is O(1).
    public static void main(String[] args) {
        show();
        cnt[0] += 5;                               // get("A") five times: count changed in place
        System.out.println("A is read 5 times; its count is changed inside the heap, no re-heapify");
        show();
        System.out.println("heap top says: evict " + key[0] + " (count " + cnt[0] + ")");
        int m = trueMin();
        System.out.println("true least frequent: " + key[m] + " (count " + cnt[m] + ")");
        siftDown(0);
        System.out.println("after siftDown(0):");
        show();
        System.out.println("heap top says: evict " + key[0] + " (count " + cnt[0] + ")");
    }
}

