code.java:
public class Main {
    // Push n items into an array that doubles when full; count how many element copies happen.
    static void measure(int n) {
        int cap = 1, size = 0;
        long copies = 0, worst = 0;
        for (int i = 0; i < n; i++) {
            if (size == cap) {                 // full: allocate double and copy everything over
                copies += size;
                worst = Math.max(worst, size); // the most expensive single push so far
                cap *= 2;
            }
            size++;                            // the push itself: 1 step
        }
        // Worst case for one push is O(n), but the total stays below 2n: amortised O(1).
        System.out.println("n=" + n + ": " + copies + " copies in total, costliest push copied " + worst
            + ", total below 2n: " + (copies < 2L * n ? "yes" : "no"));
    }
    // Time: O(n) for n pushes in total. Space: O(n).
    public static void main(String[] args) {
        System.out.println("pushes into a dynamic array that starts at capacity 1 and doubles");
        for (int n : new int[]{10, 100, 1000, 100000}) measure(n);
    }
}

