import java.util.*;

public class Main {
    static final int W = 5;                               // window: the last 5 seconds

    // Runs 2000 random operations on the fast structure and on a slow, obviously correct one.
    static int run(int seed, boolean bug) {
        int[] times = new int[W], counts = new int[W];
        Arrays.fill(times, -100);
        List<Integer> all = new ArrayList<>();            // reference: remember every hit
        int t = 0, mismatches = 0;
        for (int step = 0; step < 2000; step++) {
            seed = (seed * 75 + 74) % 65537;              // seeded generator: same sequence every run
            t += seed % 3;                                // time moves forward by 0, 1 or 2
            if ((seed / 3) % 2 == 0) {                    // operation: hit
                int i = t % W;
                if (times[i] != t) { times[i] = t; counts[i] = 0; }
                counts[i]++;
                all.add(t);
            } else {                                      // operation: query both and compare
                int fast = 0, slow = 0;
                for (int i = 0; i < W; i++)
                    if (bug ? t - times[i] <= W : t - times[i] < W) fast += counts[i];
                for (int x : all) if (t - x < W) slow++;
                if (fast != slow) mismatches++;
            }
        }
        return mismatches;
    }
    // Time: O(ops * history) because the reference is deliberately simple. Space: O(ops).
    public static void main(String[] args) {
        System.out.println("hit counter vs brute-force list, window 5, seed 42, 2000 random operations");
        System.out.println("correct version (t - time < 5):  " + run(42, false) + " mismatches");
        System.out.println("buggy version   (t - time <= 5): " + run(42, true) + " mismatches");
    }
}

