                if (bug ? t - times[i] <= W : t - times[i] < W) fast += counts[i];
            for (int x : all) if (t - x < W) slow++;
            if (fast != slow) mismatches++;
        }
    }
    return mismatches;
}
// Time: O(ops * history) because the reference is deliberately simple. Space: O(ops).
int main() {
    cout << "hit counter vs brute-force list, window 5, seed 42, 2000 random operations\n";
    cout << "correct version (t - time < 5):  " << run(42, false) << " mismatches\n";
    cout << "buggy version   (t - time <= 5): " << run(42, true) << " mismatches\n";
    return 0;
}

