using System;
using System.Collections.Generic;

class Program {
    const int W = 5;                                      // window: the last 5 seconds

    // Runs 2000 random operations on the fast structure and on a slow, obviously correct one.
    static int Run(int seed, bool bug) {
        int[] times = new int[W], counts = new int[W];
        for (int i = 0; i < W; i++) times[i] = -100;
        List<int> all = new List<int>();                  // reference: remember every hit
        int t = 0, mismatches = 0;
        for (int step = 0; step < 2000; step++) {
            seed = (seed * 75 + 74) % 65537;              // seeded generator: same sequence every run
            t += seed % 3;                                // time moves forward by 0, 1 or 2
            if ((seed / 3) % 2 == 0) {                    // operation: hit
                int i = t % W;
                if (times[i] != t) { times[i] = t; counts[i] = 0; }
                counts[i]++;
                all.Add(t);
            } else {                                      // operation: query both and compare
                int fast = 0, slow = 0;
                for (int i = 0; i < W; i++)
                    if (bug ? t - times[i] <= W : t - times[i] < W) fast += counts[i];
                foreach (int x in all) if (t - x < W) slow++;
                if (fast != slow) mismatches++;
            }
        }
        return mismatches;
    }
    // Time: O(ops * history) because the reference is deliberately simple. Space: O(ops).
    static void Main() {
        Console.WriteLine("hit counter vs brute-force list, window 5, seed 42, 2000 random operations");
        Console.WriteLine("correct version (t - time < 5):  " + Run(42, false) + " mismatches");
        Console.WriteLine("buggy version   (t - time <= 5): " + Run(42, true) + " mismatches");
    }
}
